import { useState, useEffect, useRef, useCallback } from 'react';
import TerminalWindow from './TerminalWindow';
import { wsUrl, apiFetch } from '../auth';

/**
 * StubbornWindow — wraps TerminalWindow with a thumbnail sidebar showing
 * presentations generated by this stubborn session (visible=false).
 */
export default function StubbornWindow({
  sessionId, name, presentations, onOpenPresentation, terminalProps,
}) {
  const [stubbornSessionId, setStubbornSessionId] = useState(null);
  const [sessionState, setSessionState] = useState(null);
  const wsRef = useRef(null);
  const [thumbsCollapsed, setThumbsCollapsed] = useState(false);

  // Find the stubborn brain session ID by polling awserv
  useEffect(() => {
    let cancelled = false;
    const poll = async () => {
      for (let i = 0; i < 30 && !cancelled; i++) {
        try {
          const res = await apiFetch('/api/stubborn/sessions');
          const sessions = await res.json();
          if (sessions.length > 0) {
            // Pick the most recent session (by created_at)
            const sorted = sessions.sort((a, b) => b.created_at - a.created_at);
            setStubbornSessionId(sorted[0].session_id);
            setSessionState(sorted[0]);
            return;
          }
        } catch {}
        await new Promise(r => setTimeout(r, 2000));
      }
    };
    poll();
    return () => { cancelled = true; };
  }, [sessionId]);

  // Connect to stubborn WebSocket for real-time state updates
  useEffect(() => {
    if (!stubbornSessionId) return;
    const ws = new WebSocket(wsUrl(`/ws/stubborn/${stubbornSessionId}`));
    wsRef.current = ws;
    ws.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);
        if (msg.type === 'session_init' || msg.type === 'session_updated') {
          setSessionState(msg.session);
        }
        if (msg.type === 'token_update') {
          setSessionState(prev => prev ? { ...prev, tokens_used: msg.used, cycle: msg.cycle } : prev);
        }
      } catch {}
    };
    ws.onclose = () => { wsRef.current = null; };
    return () => { ws.close(); };
  }, [stubbornSessionId]);

  // Filter presentations: visible=false AND tied to this stubborn session
  const sessionPresentations = (presentations || []).filter(c =>
    c.visible === false && (
      c.session_id === stubbornSessionId ||
      // Also show presentations without a session_id if they're hidden (for backwards compat)
      (!c.session_id && c.visible === false)
    )
  );

  const formatTokens = (n) => {
    if (!n) return '0';
    if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
    return String(n);
  };

  return (
    <div className="w-full h-full flex rounded-lg overflow-hidden shadow-2xl shadow-black/40 border border-[var(--color-border)]">
      {/* Main terminal area */}
      <div className={`flex-1 flex flex-col min-w-0 ${!thumbsCollapsed && sessionPresentations.length > 0 ? '' : 'w-full'}`}>
        {/* Stubborn status bar */}
        {sessionState && (
          <div className="flex items-center gap-3 px-3 py-1.5 bg-[#1a1020] border-b border-[var(--color-border)] text-[11px] font-mono shrink-0">
            <span className="flex items-center gap-1.5">
              <span className={`w-2 h-2 rounded-full ${
                sessionState.status === 'running' ? 'bg-green-500 animate-pulse' :
                sessionState.status === 'completed' ? 'bg-blue-400' :
                sessionState.status === 'created' ? 'bg-gray-400' :
                'bg-yellow-400'
              }`} />
              <span className="text-[var(--color-text-muted)] uppercase tracking-wider">{sessionState.status}</span>
            </span>
            <span className="text-[var(--color-text-secondary)]">
              Cycle <span className="text-[var(--color-text-primary)]">{sessionState.cycle}</span>
              <span className="text-[var(--color-text-muted)]">/{sessionState.max_cycles}</span>
            </span>
            <span className="text-[var(--color-text-secondary)]">
              Tokens <span className="text-[var(--color-text-primary)]">{formatTokens(sessionState.tokens_used)}</span>
              <span className="text-[var(--color-text-muted)]">/{formatTokens(sessionState.token_limit)}</span>
            </span>
            {sessionState.evidence?.length > 0 && (
              <span className="text-[var(--color-text-secondary)]">
                Evidence <span className="text-emerald-400">{sessionState.evidence.length}</span>
              </span>
            )}
            {Object.keys(sessionState.agents || {}).length > 0 && (
              <span className="text-[var(--color-text-secondary)]">
                Agents <span className="text-purple-400">{Object.keys(sessionState.agents).length}</span>
              </span>
            )}
            <span className="flex-1" />
            {sessionState.goal && (
              <span className="text-[var(--color-text-muted)] truncate max-w-[300px]" title={sessionState.goal}>
                {sessionState.goal}
              </span>
            )}
          </div>
        )}
        {/* Terminal */}
        <div className="flex-1 min-h-0">
          <TerminalWindow {...terminalProps} />
        </div>
      </div>

      {/* Thumbnail sidebar */}
      {sessionPresentations.length > 0 && (
        <div className={`flex flex-col border-l border-[var(--color-border)] bg-[var(--color-bg-secondary)] transition-all ${thumbsCollapsed ? 'w-8' : 'w-48'}`}>
          {/* Toggle button */}
          <button
            onClick={() => setThumbsCollapsed(!thumbsCollapsed)}
            className="p-1.5 text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] hover:bg-white/5 transition-colors border-b border-[var(--color-border)]"
            title={thumbsCollapsed ? 'Show thumbnails' : 'Hide thumbnails'}
          >
            <svg className={`w-3.5 h-3.5 mx-auto transition-transform ${thumbsCollapsed ? 'rotate-180' : ''}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M15 18l-6-6 6-6" />
            </svg>
          </button>

          {!thumbsCollapsed && (
            <div className="flex-1 overflow-y-auto p-2 space-y-2">
              <div className="text-[10px] font-semibold uppercase tracking-wider text-[var(--color-text-muted)] px-1">
                Presentations ({sessionPresentations.length})
              </div>
              {sessionPresentations.map(presentation => (
                <button
                  key={presentation.id}
                  onClick={() => onOpenPresentation?.(presentation.id)}
                  className="w-full rounded-md overflow-hidden border border-[var(--color-border)] hover:border-[var(--color-accent)] transition-colors cursor-pointer group"
                  title={presentation.title}
                >
                  {/* Thumbnail preview — render presentation HTML in a tiny scaled iframe */}
                  <div className="w-full h-20 bg-[var(--color-bg-primary)] relative overflow-hidden">
                    <iframe
                      srcDoc={presentation.html
                        ?.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
                        ?.replace(/\s+on\w+="[^"]*"/gi, '')
                        ?.replace(/\s+on\w+='[^']*'/gi, '')}
                      className="absolute top-0 left-0 border-0 pointer-events-none"
                      style={{ width: '768px', height: '400px', transform: 'scale(0.234)', transformOrigin: 'top left' }}
                      title={presentation.title}
                      sandbox=""
                    />
                  </div>
                  <div className="px-1.5 py-1 text-[10px] text-[var(--color-text-secondary)] truncate group-hover:text-[var(--color-text-primary)] transition-colors">
                    {presentation.title}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
